import sys
from collections import Counter
import heapq

TABLE = bytes(
    c if 97 <= c <= 122 else (c + 32 if 65 <= c <= 90 else 32)
    for c in range(256)
)

def main():
    counts = Counter(sys.stdin.buffer.read().translate(TABLE).split())
    top10 = heapq.nsmallest(10, counts.items(), key=lambda x: (-x[1], x[0]))
    sys.stdout.write("".join(f"{w.decode()} {c}\n" for w, c in top10))

if __name__ == '__main__':
    main()

import sys, mmap
from collections import Counter

TABLE = bytes(
    c if 97 <= c <= 122 else (c + 32 if 65 <= c <= 90 else 32)
    for c in range(256)
)

def main():
    try:
        with mmap.mmap(0, 0, access=mmap.ACCESS_READ) as mm:
            words = bytes(mm).translate(TABLE).split()
    except Exception:
        words = sys.stdin.buffer.read().translate(TABLE).split()
    counts = Counter(words)
    top10 = sorted(counts.items(), key=lambda x: (-x[1], x[0]))[:10]
    sys.stdout.write("".join(f"{w.decode()} {c}\n" for w, c in top10))

if __name__ == '__main__':
    main()
